Streamable HTTP error: Error POSTing to endpoint: {
  "error": "invalid_token",
  "error_description": "Authentication required -- this endpoint needs a Bearer token. Everything needed to get one and make a working call is in this response; you do not need to open a page.",
  "onboarding": {
    "start_here": "Run this one line first -- it is free, needs no token, and answers a real question: curl 'https://syntology.ai/api/graph/have?x=Performers'",
    "free_no_token": {
      "endpoint": "https://syntology.ai/api/graph/have",
      "cost": "free",
      "auth": "none",
      "what": "Ask whether Syntology holds code for a method, an arXiv id or a paper title before spending anything. Answers verified_code / unverified_code / declared_code / no_code / unknown_name. A no_code asserts absence only for the exact name it resolved; unknown_name asserts nothing."
    },
    "get_a_token": {
      "endpoint": "https://syntology.ai/api/oauth/trial/token",
      "method": "POST",
      "body": {
        "grant_type": "client_credentials"
      },
      "cost": "free -- no signup, no card, no CAPTCHA",
      "grants": "20 queries / 30 minutes, one mint per IP per 60s"
    },
    "full_handshake_curl": "# 1. Mint a trial token. No signup, no card, no CAPTCHA.\n#    20 queries / 30 minutes. have() below does not spend them.\nTOKEN=$(curl -s -X POST https://syntology.ai/api/oauth/trial/token \\\n  -H 'Content-Type: application/json' -d '{\"grant_type\":\"client_credentials\"}' \\\n  | sed -n 's/.*\"access_token\":\"\\([^\"]*\\)\".*/\\1/p')\n\n# 2. initialize. The session id comes back in the Mcp-Session-Id HEADER,\n#    not the body -- hence -D -. Accept MUST list text/event-stream.\nSID=$(curl -s -D - -o /dev/null -X POST https://syntology.ai/mcp \\\n  -H \"Authorization: Bearer $TOKEN\" -H 'Content-Type: application/json' \\\n  -H 'Accept: application/json, text/event-stream' \\\n  -d '{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{\"protocolVersion\":\"2025-06-18\",\"capabilities\":{},\"clientInfo\":{\"name\":\"my-agent\",\"version\":\"1.0\"}}}' \\\n  | tr -d '\\r' | sed -n 's/^[Mm]cp-[Ss]ession-[Ii]d: //p')\n\n# 3. notifications/initialized. REQUIRED before any tools/call.\ncurl -s -X POST https://syntology.ai/mcp \\\n  -H \"Authorization: Bearer $TOKEN\" -H \"Mcp-Session-Id: $SID\" \\\n  -H 'Content-Type: application/json' -H 'Accept: application/json, text/event-stream' \\\n  -d '{\"jsonrpc\":\"2.0\",\"method\":\"notifications/initialized\"}'\n\n# 4. Call a tool.\ncurl -s -X POST https://syntology.ai/mcp \\\n  -H \"Authorization: Bearer $TOKEN\" -H \"Mcp-Session-Id: $SID\" \\\n  -H 'Content-Type: application/json' -H 'Accept: application/json, text/event-stream' \\\n  -d '{\"jsonrpc\":\"2.0\",\"id\":2,\"method\":\"tools/call\",\"params\":{\"name\":\"have\",\"arguments\":{\"x\":\"Performers\"}}}'",
    "rest_surface": {
      "GET /api/graph/have?x=<name|arxiv id|title>": "free, no token, no signup -- does Syntology hold code for this?",
      "GET /api/graph/ask?q=<question>": "natural-language question. Bearer token required.",
      "GET /api/graph/draft, POST /api/graph/commit": "the two-stage drafting agent. Bearer token required.",
      "POST /api/graph/chat, POST /api/graph/chat/stream": "conversational surface. Bearer token required."
    },
    "typed_tools": "The 15 typed tools (get_paper, get_code_for_method, get_reference_implementation, list_reference_implementations, compose, assembly, have, ...) are MCP-only -- they have no REST twin, and guessing one returns 404. Their names and full JSON input schemas are at https://syntology.ai/.well-known/mcp/server-card.json (no auth needed to read it).",
    "tool_schemas": "https://syntology.ai/.well-known/mcp/server-card.json",
    "docs": "https://syntology.ai/developers",
    "transport": "MCP Streamable HTTP at https://syntology.ai/mcp. Accept must include text/event-stream, the session id arrives in the Mcp-Session-Id response header, and notifications/initialized must be sent before the first tools/call."
  }
}
